const rawUser = {
  id: "usr_91Xk2",
  username: "dev_bren",
  email: "bren@example.com",
  saltToken: "****"
};

// Remove sensitive fields before sending to client
const safeUser = transformXalor<"User", "omit">({
  mode: "omit",
  data: rawUser,
  keys: ["passwordHash", "saltToken"]
});

// Keep only what the UI needs
const publicUser = transformXalor<"User", "pick">({
  mode: "pick",
  data: safeUser,
  keys: ["id", "username", "email"]
});

