import { xalor } from '@bgskinner2/xalor'; 

/** Define your user model */ 
type TUser = { 
  id: number; 
  username: string; 
  email: string; 
  displayName: string; 
  avatarUrl: string; 
  active: boolean; 
  role: 'user' | 'moderator' | 'admin'; 
  createdAt: Date; 
  lastLoginAt: Date; 
}; 

/** Register schema in xalor registry */ 
xalor.register<'USER_PROFILE', TUser>(); 

/** Raw API response (untrusted external input) */ 
const apiResponse: unknown = { 
  id: 901, 
  username: 'bounce_parse_pass', 
  email: 'userEmail@example.com', 
  displayName: 'Bounce Parse Pass', 
  avatarUrl: 'https://i.pravatar.cc/150?img=12', 
  active: true, 
  role: 'user', 
  createdAt: '2025-01-10T10:00:00Z', 
  lastLoginAt: '2026-06-13T18:30:00Z' 
}; 

/** Field-level validation rules */ 
const validators = { 
  email: (value) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value) 
}; 

/** Parse + validate into strongly typed USER_PROFILE model */ 
const parsedResponse = xalor.parse<'USER_PROFILE'>(apiResponse, validators);

