import { xalor } from '@bgskinner2/xalor'; 
/**
 * Define your user model
 */
type TUser = {
  id: number;
  username: string;
  email: string;
  preferences: {
    theme: 'dark' | 'light';
    notifications: boolean;
    locale: string;
  };
  stats: {
    posts: number;
    followers: number;
    following: number;
  };
};

/**
 * Register the schema key → type mapping
 */
xalor.register<'USER_PROFILE', TUser>();

const legacyPayload: unknown = {
  id: 44102,
  username: 'selina_kyle',
  userTheme: 'dark', // ❌ Mismatch: Field was removed in today's V2 production schema model!
};

/**
 * Drift-driven schema migration layer
 */
const sanitizedPayload = xalor.drift<'USER_PROFILE'>(legacyPayload, {
  /**
   * Branch 1: Current V2 shape (pass-through)
   */
  current: (v2User) => v2User,

  /**
   * Branch 2: V1 → V2 migration bridge
   */
  v1_ancestor: (v1Account) => {
    // 🚀 Active In-Memory Upcasting! Convert 'userTheme' into the new nested object layout.
    return {
      ...v1Account,
      preferences: {
        theme: v1Account.userTheme === 'dark' ? 'dark' : 'light',
        notifications: false,
        locale: 'en-US',
      },
    };
  },
});

// The Exact Materialized V2 Object Layout Returned (Result)
